    @EventHandler( payloadType=CreateTagEvent.class )
    public void handle( CreateTagEvent event) {
	    LOGGER.info("handling CreateTagEvent - " + event );
	    Tag entity = new Tag();
            entity.setTagId( event.getTagId() );
            entity.setName( event.getName() );
            entity.setCategory( event.getCategory() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllTag( entity );
    }

