    /**
     * Method to retrieve the Tag via an TagPrimaryKey.
     * @param 	id Long
     * @return 	Tag
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Tag handle( FindTagQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTagId() );
    }
    
    /**
     * Method to retrieve a collection of all Tags
     *
     * @param	query	FindAllTagQuery 
     * @return 	List<Tag> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Tag> handle( FindAllTagQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTag,
 * but only if the id matches
 *
 * @param		entity	Tag
 */
	protected void emitFindTag( Tag entity ) {
		LOGGER.info("handling emitFindTag" );
		
	    queryUpdateEmitter.emit(FindTagQuery.class,
	                            query -> query.getFilter().getTagId().equals(entity.getTagId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTag
	 * 
	 * @param		entity	Tag
	 */
	protected void emitFindAllTag( Tag entity ) {
		LOGGER.info("handling emitFindAllTag" );
		
	    queryUpdateEmitter.emit(FindAllTagQuery.class,
	                            query -> true,
	                            entity);
	}

